// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      answersUrl: 'assets/medvezhonok/' + year + '/' + grade + '-answers.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2024, "2-3", [{"author":"А. Сомин","question":"Что бывает сахарным и радует множество детей?","choices":["гипс","бинты","вата","пластырь","марля."],"key":"В","review":["Сахарное угощение","Подумай о сладости, которую делают из сахара и наматывают на палочку. Она лёгкая, воздушная и похожа на мягкое облачко.","По виду она напоминает обычную вату, поэтому её называют сахарной ватой. Остальные слова обозначают материалы для повязки или лечения."]},{"author":"А. Ковалёва","question":"Петя зашёл в магазине в отдел «Зимние спортивные товары». «А это должно быть в другом отделе», — сказал он. Что имел в виду мальчик?","choices":["санки","лыжи","коньки","ласты","снегокат."],"key":"Г","review":["Отдел зимних товаров","Для санок, лыж и снегоката нужен снег, а для коньков — лёд. Все эти вещи подходят для зимнего отдела.","Ласты надевают, чтобы плавать. Их место в отделе товаров для плавания."]},{"author":"Е. Муравенко","question":"В каком предложении выделенное слово имеет не такое значение, как в остальных?","choices":["Аня <strong>погладила</strong> своего котёнка.","Саша достал с полки любимую книгу и <strong>погладил</strong> обложку.","Мама <strong>погладила</strong> Мише рубашку.","Бабушка <strong>погладила</strong> внучку по голове и попрощалась.","Дед неспешно <strong>погладил</strong> окладистую бороду."],"key":"В","review":["Что значит «погладить»","В четырёх предложениях можно представить, как кто-то проводит ладонью по котёнку, обложке, голове или бороде.","Мама гладит рубашку утюгом, чтобы расправить складки. Только здесь «погладить» значит «прогладить утюгом»."]},{"author":"Е. Муравенко","question":"Из букв А, В, И, К, Н, О, Р, Т можно составить название дня недели, но одна буква окажется лишней. Какая?","choices":["А","В","И","К","Н."],"key":"А","review":["День недели из букв","Сравни длину названий дней недели. Из восьми выданных букв нужно использовать семь. Семь букв в слове «вторник».","Сложи В, Т, О, Р, Н, И, К. Все они есть в наборе, остаётся только буква А."]},{"author":"О. Подлесская","question":"Прочитайте отрывок из стихотворения Марины Бородицкой «На снегу»:\n<em>До утра мели метели,\nА с утра по склонам\nПокатили-полетели\nАпельсин с лимоном!\nЗа морковкой помидор\nНа санях несутся с гор.\n\nБаклажан и огурец\nСтроят снеговой дворец.\nЧто за сад-огород,\nЯблоки-лимоны?\nВсех цветов комбинезоны,\nКуртки, капюшоны!</em>\nКакой цвет не представлен в этом отрывке?","choices":["красный","оранжевый","жёлтый","зелёный","голубой."],"key":"Д","review":["Цветной спуск с горы","Дети в яркой одежде напоминают автору фрукты и овощи. Найди красный у помидора, оранжевый у морковки и апельсина, жёлтый у лимона, зелёный у огурца.","Даже баклажан добавляет ещё один цвет — фиолетовый. Среди перечисленных фруктов и овощей ничто не подсказывает голубой."]},{"author":"О. Подлесская","question":"Какое слово противоположно по смыслу слову <em>шершавый</em>?","choices":["<em>глубокий</em>","<em>широкий</em>","<em>тяжёлый</em>","<em>громкий</em>","<em>гладкий</em>."],"key":"Д","review":["Какая поверхность","Проведи пальцем по наждачной бумаге или грубой коре. «Шершавой» называют поверхность с мелкими неровностями.","Поверхность без таких неровностей называют гладкой. Сверь два примера: шершавая кора и гладкое стекло."]},{"author":"И. Иткин и Л. Иткин","question":"Какое действие нельзя выполнить в одиночку?","choices":["<em>переодеть</em>","<em>перепрыгнуть</em>","<em>переместиться</em>","<em>перевернуться</em>","<em>переглянуться</em>."],"key":"Д","review":["Одному или вдвоём","Представь каждое действие. Можно переодеть куклу или одному перепрыгнуть через лужу, переместиться и перевернуться.","Переглянуться — обменяться взглядами. Чтобы посмотреть друг на друга, нужны хотя бы двое."]},{"author":"А. Пиперски","question":"В каком выражении обычно не пропускают слово <em>час</em>?","choices":["<em>семь часов утра</em>","<em>десять часов утра</em>","<em>три часа дня</em>","<em>шесть часов вечера</em>","<em>одиннадцать часов вечера</em>."],"key":"В","review":["Как называют время","Скажи коротко: «семь утра», «десять утра», «шесть вечера», «одиннадцать вечера». И без слова «часов» понятно, что это время суток.","«Три дня» обычно означает срок в трое суток, поэтому время называют «три часа дня». Слово «часа» помогает различить эти два смысла."]},{"author":"Л. Фёдорова","question":"<em>Мягкое «мяу»\nГуляло по саду.\nМестное «ме-е»\nОбдирало ограду.\nИ призадумалось\nМудрое «му-у»:\n— Где посвежее трава,\nНе пойму...</em>\nНазовите по порядку животных, о которых говорится в стихотворении Михаила Яснова.","choices":["корова, коза, кошка","коза, кошка, корова","кошка, овечка, лошадь","кошка, корова, овечка","кошка, коза, корова."],"key":"Д","review":["Голоса в стихотворении","Прочитай звуки по порядку: «мяу», «ме-е», «му-у». Первый выдаёт кошку, последний — корову.","Ограду обдирает коза: она может объедать листья и ветки рядом с ней. В стихотворении получаем порядок «кошка, коза, корова»."]},{"author":"Е. Муравенко","question":"Какое слово лишнее по смыслу?","choices":["<em>аккуратный</em>","<em>решительный</em>","<em>смелый</em>","<em>отважный</em>","<em>храбрый</em>."],"key":"А","review":["Черты характера","«Смелый», «отважный» и «храбрый» — о тех, кто не боится опасности. Решительный человек готов действовать, даже если трудно.","Аккуратный человек делает всё тщательно и следит за порядком. Это другое качество, поэтому слово «аккуратный» лишнее."]},{"author":"И. Рубанов","question":"Учитель написал на доске несколько букв и попросил учеников составить из них слова. Петя составил слова <em>лом</em>, <em>том</em>, <em>стол</em>. Оказалось, что два из них он составил правильно, а одно — неправильно. Какой буквы не было на доске?","choices":["<em>л</em>","<em>м</em>","<em>о</em>","<em>с</em>","<em>т</em>."],"key":"Г","review":["Буквы на школьной доске","Проверь, в скольких словах нужна каждая буква. Л есть в «лом» и «стол», М — в «лом» и «том», Т — в «том» и «стол», О есть во всех трёх.","Без любой из этих букв неверными оказались бы хотя бы два слова. Только С нужна одному слову «стол», поэтому на доске не было С."]},{"author":"Б. Иомдин","question":"Даны три китайских слова: 凹, 凹凸, 凸. А что они означают?","choices":["выпуклый, бугристый, вогнутый","бугристый, вогнутый, выпуклый","вогнутый, бугристый, выпуклый","выпуклый, вогнутый, бугристый","вогнутый, выпуклый, бугристый."],"key":"В","review":["Формы китайских знаков","Взгляни на очертания: сверху у 凹 углубление, а у 凸 выступ. Они похожи на рисунки вогнутой и выпуклой поверхностей.","凹 означает «вогнутый», 凸 — «выпуклый». Вместе 凹凸 дают «бугристый», где чередуются впадины и выступы. Порядок — вогнутый, бугристый, выпуклый."]},{"author":"А. Сомин","question":"Венгерское слово, которое звучит как «вилланькёрте», значит ‘лампочка’. Слово «виллань» переводится как <em>электричество</em>. А как переводится слово «кёрте»?","choices":["<em>яблоко</em>","<em>груша</em>","<em>слива</em>","<em>персик</em>","<em>орех</em>."],"key":"Б","review":["Венгерское слово для лампы","Первую часть «вилланькёрте» уже перевели как «электричество». Вторая часть может назвать знакомый предмет, похожий на лампочку.","У обычной лампочки круглый верх и узкое основание, как у груши. Венгерское «кёрте» означает «груша»."]},{"author":"Е. Муравенко","question":"В четырёх из данных слов можно заменить букву <strong>с</strong> буквой <strong>ж</strong> и получить новое слово. В каком слове так сделать нельзя?","choices":["<em>лось</em>","<em>морс</em>","<em>сало</em>","<em>сук</em>","<em>сыр</em>."],"key":"Д","review":["Замена одной буквы","Поменяй С на Ж: «лось» даёт «ложь», «морс» — «морж», «сало» — «жало», а «сук» — «жук».","В слове «сыр» получится «жыр». Такого слова нет, а для «жир» пришлось бы заменить ещё и Ы на И."]},{"author":"А. Ковалёва","question":"У какого детёныша название матери похоже на его название, а название отца — нет?","choices":["у ягнёнка","у гусёнка","у утёнка","у цыплёнка","у медвежонка."],"key":"В","review":["Как зовут родителей","Сопоставь названия двух семей: гусыня и гусь похожи на «гусёнок», медведица и медведь — на «медвежонок». У ягнёнка и цыплёнка оба родительских названия звучат иначе: овца и баран, курица и петух.","У утёнка мама — утка, папа — селезень. Только в этой семье детёныша легко узнать по названию матери, а у отца совсем другое слово."]},{"author":"А. Сомин","question":"Какое из этих предложений имеет смысл?","choices":["<em>Волшебника интересует волшебника.</em>","<em>Музыка интересует музыка.</em>","<em>Гимнастика интересует гимнастика</em>.","<em>Поликлиника интересует поликлиника.</em>","<em>Математика интересует математика.</em>"],"key":"Д","review":["Кого что интересует","В предложении «Книги интересуют ученика» есть ответ на два вопроса: «что интересует?» и «кого?». Проверь, какие варианты дают обе нужные формы.","«Математика» может означать науку, а «математика» на вопрос «кого?» — человека, математика. Поэтому «Математика интересует математика» — осмысленная фраза."]},{"author":"Л. Фёдорова","question":"В начале одной шведской сказки перепутались фразы. Помогите расставить их в правильном порядке.\n1. Однажды, когда он в очередной раз чего-то захотел, один мудрый старик дал ему совет.\n2. Старик предложил мальчику пойти в лес и насыпать сороке соли на хвост — тогда все его желания исполнятся.\n3. То он мечтал о маленькой лошадке, на которой можно кататься верхом, то о санках, то о лодке, то о складном ноже.\n4. Жил когда-то мальчик, которому всегда чего-нибудь хотелось.\n5. Но, так как отец мальчика умер, а мать была бедной, его желания никогда не исполнялись.\n6. С этого дня мальчик всегда носил соль в кармане штанов.","choices":["1-2-5-6-4-3","2-6-5-3-1-4","4-1-2-6-5-3","4-5-1-2-3-6","4-3-5-1-2-6."],"key":"Д","review":["Мальчик и совет старика","Начинаем с фразы «Жил когда-то мальчик» (4). Потом перечисляем его мечты (3) и узнаём, почему они не исполнялись (5).","Старик даёт совет (1), затем объясняется, в чём он состоял (2). После этого мальчик носит соль (6). Порядок — 4, 3, 5, 1, 2, 6."]},{"author":"О. Подлесская","question":"Оля выписывала интересные рифмы в стихах Самуила Маршака. Четыре примера обладают одной особенностью, а пятый — нет. Найдите его.","choices":["<em>Сунул ключик в замочную щёлку,\nА замок отомкнулся и щёлкнул.</em>","<em>Весёлые сцены,\nДешёвые цены.</em>","<em>С двух сторон ему еноты\nПерелистывают ноты.</em>","<em>Без сквозняков и без ребят,\nЧто за хвосты нас теребят.</em>","<em>Боюсь, что олени\nСломают колени.</em>"],"key":"А","review":["Рифмы Маршака","Сравни последние слова строк. «Цены» целиком есть в «сцены», «ноты» — в «еноты», «ребят» — в «теребят», «олени» — в «колени».","«Щёлку» и «щёлкнул» похожи по звучанию, но ни одно из слов не входит целиком в другое. Это и есть отличающийся пример."]},{"author":"Л. Фёдорова","question":"В какой паре слов множественное число образуется одинаково?","choices":["<em>мать</em> и <em>отец</em>","<em>сын</em> и <em>дочь</em>","<em>брат</em> и <em>сестра</em>","<em>дедушка</em> и <em>бабушка</em>","во всех парах множественное число образуется по-разному."],"key":"Г","review":["Семья во множественном числе","Назови несколько человек: матери и отцы, сыновья и дочери, братья и сёстры. В этих парах слова меняются по-разному.","«Дедушка — дедушки» и «бабушка — бабушки» меняются одинаково: конечное А заменяется на И. Значит, подходит четвёртая пара."]},{"author":"Е. Муравенко","question":"Вставьте пропущенные буквы в слова: <em>с_бака</em>, <em>тр_ва</em>, <em>тет_адь</em>, <em>пиро_</em>, <em>расска_</em>. Какое слово можно получить из вставленных букв?","choices":["<em>горка</em>","<em>гроза</em>","<em>загар</em>","<em>краса</em>","<em>окрас</em>."],"key":"Б","review":["Буквы из пропусков","Заполни пропуски: «собака», «трава», «тетрадь», «пирог», «рассказ». Выпиши только вставленные буквы: О, А, Р, Г, З.","Поставь Г первой и переставь остальные буквы: Г, Р, О, З, А. Все пять букв использованы, и получается «гроза»."]},{"author":"Е. Муравенко","question":"Дождь <strong>не</strong> может быть _____.","choices":["проливной","дождливый","грибной","моросящий","затяжной."],"key":"Б","review":["Каким бывает дождь","Проливной дождь сильный, моросящий сыплет мелкими каплями, затяжной идёт долго. Грибным называют лёгкий дождь, нередко при солнце.","Дождливым может быть день, лето или время года, когда дождь идёт часто. О самом дожде так не говорят."]},{"author":"Б. Иомдин","question":"Детям подарили прозрачные двусторонние магнитики с их именами, написанными заглавными буквами. Кто из них сможет повесить на холодильник свой магнитик только одной стороной?","choices":["Ада","Натан","Анна","Тит","все смогут повесить магнитики обеими сторонами."],"key":"Г","review":["Две стороны магнитика","Переверни прозрачную надпись мысленно. Буквы читаются в обратном порядке и отражаются. Все имена читаются одинаково с двух концов, так что решает форма букв.","Заглавные А, Д, Н и Т симметричны слева направо. У И отражается наклонная черта, поэтому «ТИТ» выглядит правильно только с одной стороны."]},{"author":"Е. Муравенко","question":"<em>На столе лежали мамины бусы, очки, часы, ручки и весы.</em>\nКакое наименьшее количество предметов могло лежать на столе?","choices":["пять","шесть","семь","девять","десять."],"key":"Б","review":["Сколько вещей на столе","Бусы, очки, часы и весы можно назвать так, даже если на столе лежит по одному предмету каждого вида. Это уже четыре предмета.","«Ручки» — множественное число от «ручка», значит, их хотя бы две. Самое маленькое число предметов — четыре плюс два, то есть шесть."]},{"author":"А. Сомин","question":"Для обозначения аэропортов в России используются так называемые внутренние коды. Выберите правильный порядок кодов для аэропортов Владивостока, Владикавказа и Владимира.","choices":["ВЛА, ВВО, ВЛМ","ВЛМ, ВЛА, ВВО","ВЛА, ВЛМ, ВВО","ВВО, ВЛА, ВЛМ","ВВО, ВЛМ, ВЛА."],"key":"Г","review":["Коды трёх аэропортов","Присмотрись к буквам в кодах. ВВО можно связать с названием «Владивосток»: первое В берётся из начала слова, ВО — из «восток».","ВЛМ отличает Владимир, в имени которого есть М. ВЛА остаётся Владикавказу. В нужном порядке — ВВО, ВЛА, ВЛМ."]},{"author":"А. Сомин","question":"Первое слово обозначает то, в чём ездили двести лет назад. Если в этом слове поменять местами две буквы, то получится второе слово — то, на чём можно летать. О каких двух буквах идёт речь?","choices":["<em>к</em> и <em>р</em>","<em>м</em> и <em>с</em>","<em>р</em> и <em>т</em>","<em>в</em> и <em>п</em>","<em>г</em> и <em>л</em>."],"key":"А","review":["Из экипажа в полёт","Старинный экипаж, в котором ездили люди, — «карета». Слово похоже на название того, на чём можно летать, — «ракета».","Сравни К-А-Р-Е-Т-А и Р-А-К-Е-Т-А. Буквы К и Р поменялись местами, остальные остались на своих местах."]},{"author":"Е. Муравенко","question":"Сколько раз в этих строчках из стихотворения «Жарко» Агнии Барто встречается твёрдый звук [д]?\n<em>Обмахнулся веером\nГражданин с бородкой,\nЗашагал уверенной,\nДеловой походкой.</em>","choices":["один","два","три","четыре","ни разу."],"key":"А","review":["Твёрдый Д в стихах Барто","Произнеси слова с Д. В «бородкой» и «походкой» рядом с глухим [к] слышится [т], а в «деловой» перед Е звучит мягкий [д’].","В слове «гражданин» после Д идёт А, и слышится твёрдый звонкий [д]. В этих строках он встречается один раз."]},{"author":"И. Рубанов","question":"<em>Борщ</em>, <em>ёжик</em>, <em>аист</em>, <em>взнос</em>, _____. Все слова из этого списка обладают одним редким свойством. Какое слово можно добавить к этому списку?","choices":["<em>зонт</em>","<em>мост</em>","<em>порт</em>","<em>прут</em>","<em>страх</em>."],"key":"Б","review":["Борщ, ёжик, аист, взнос","Сравни порядок букв с алфавитом. В «борщ» идут Б, О, Р, Щ, и каждая буква позже предыдущей. Проверь так же «ёжик», «аист» и «взнос».","В «мост» М, О, С, Т стоят по алфавиту. Проверь два контрпримера: в «зонт» О стоит перед Н, а в «порт» П перед О. В алфавите они идут наоборот."]},{"author":"Б. Иомдин","question":"Учитель предложил особое задание, и дети нарисовали такие картинки. А какую картинку нарисовали сразу двое, мальчик и девочка?","choices":["","","","",""],"key":"А","review":["Рисунки учеников","Прочитай названия картинок: неваляшка, жираф, корзина. В них подряд спрятались Валя, Ира и Зина — короткие имена девочек.","На первом рисунке среди ответов коляска. В её названии есть и Коля, и Оля: «КОЛЯска» и «кОЛЯска». Значит, её могли нарисовать двое."],"figure":{"condition":{"src":"assets/medvezhonok/2024/2-3-28.webp","width":1198,"height":303,"pixelWidth":1198,"pixelHeight":303,"items":[{"src":"assets/medvezhonok/2024/2-3-28-condition-1.webp","caption":"Валентина","alt":"Неваляшка"},{"src":"assets/medvezhonok/2024/2-3-28-condition-2.webp","caption":"Ирина","alt":"Жираф"},{"src":"assets/medvezhonok/2024/2-3-28-condition-3.webp","caption":"Зинаида","alt":"Корзина"}],"alt":"Валентина нарисовала неваляшку, Ирина — жирафа, Зинаида — корзину."},"options":[{"src":"assets/medvezhonok/2024/2-3-28-1.webp","width":164,"height":193,"pixelWidth":164,"pixelHeight":193,"description":"Детская коляска"},{"src":"assets/medvezhonok/2024/2-3-28-2.webp","width":153,"height":243,"pixelWidth":153,"pixelHeight":243,"description":"Лев"},{"src":"assets/medvezhonok/2024/2-3-28-3.webp","width":193,"height":225,"pixelWidth":193,"pixelHeight":225,"description":"Изба"},{"src":"assets/medvezhonok/2024/2-3-28-4.webp","width":83,"height":181,"pixelWidth":83,"pixelHeight":181,"description":"Матрёшка"},{"src":"assets/medvezhonok/2024/2-3-28-5.webp","width":144,"height":195,"pixelWidth":144,"pixelHeight":195,"description":"Ранец"}],"onlyPictures":true}}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
